stats-trimmed-mean.solution:
def trimmed_mean(values, prop):
    xs = sorted(values)
    n = len(xs)
    k = int(prop * n)
    kept = xs[k:n - k]
    return sum(kept) / len(kept)

stats-weighted-median.solution:
def weighted_median(values, weights):
    pairs = sorted(zip(values, weights), key=lambda p: p[0])
    half = sum(weights) / 2
    run = 0.0
    for v, w in pairs:
        run += w
        if run >= half:
            return v
    return pairs[-1][0]

stats-mad-iqr.solution:
def mad_iqr(values):
    def median(v):
        s = sorted(v)
        n = len(s)
        return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2
    def pct(s, p):
        h = (len(s) - 1) * p
        j = int(h)
        if j >= len(s) - 1:
            return float(s[-1])
        return s[j] + (h - j) * (s[j + 1] - s[j])
    m = median(values)
    mad = median([abs(x - m) for x in values])
    s = sorted(values)
    return [float(mad), float(pct(s, 0.75) - pct(s, 0.25))]

stats-percentile-linear.solution:
def percentile(values, q):
    s = sorted(values)
    h = (len(s) - 1) * q / 100
    j = int(h)
    if j >= len(s) - 1:
        return float(s[-1])
    return s[j] + (h - j) * (s[j + 1] - s[j])

stats-histogram-counts.solution:
def histogram_counts(values, lo, hi, bins):
    counts = [0] * bins
    width = (hi - lo) / bins
    for x in values:
        if x < lo or x > hi:
            continue
        if x == hi:
            k = bins - 1
        else:
            k = int((x - lo) / width)
            k = min(k, bins - 1)
        counts[k] += 1
    return counts

stats-binomial-tail.solution:
import math

def binom_tail(n, p, k):
    if k <= 0:
        return 1.0
    if k > n:
        return 0.0
    total = 0.0
    for i in range(k, n + 1):
        total += math.comb(n, i) * (p ** i) * ((1 - p) ** (n - i))
    return min(total, 1.0)

