import numpy as np

def ols(X, y):
    X = np.asarray(X, dtype=float)
    A = np.column_stack([np.ones(len(X)), X])
    yv = np.asarray(y, dtype=float)
    return np.linalg.solve(A.T @ A, A.T @ yv).tolist()

stats-simpson-detect.solution:
def simpson(rows):
    def cmp(sa, ta, sb, tb):
        left, right = sb * ta, sa * tb
        return "B" if left > right else "A" if left < right else "tie"
    groups = {}
    tot = {"A": [0, 0], "B": [0, 0]}
    for g, arm, s, t in rows:
        groups.setdefault(g, {})[arm] = (s, t)
        tot[arm][0] += s
        tot[arm][1] += t
    results = {cmp(*v["A"], *v["B"]) for v in groups.values()}
    within = results.pop() if len(results) == 1 and results <= {"A", "B"} else "mixed"
    aggregate = cmp(tot["A"][0], tot["A"][1], tot["B"][0], tot["B"][1])
    paradox = within in ("A", "B") and aggregate in ("A", "B") and aggregate != within
    return [within, aggregate, paradox]

stats-confusion-metrics.solution:
def metrics_at(y_true, scores, threshold):
    tp = fp = fn = tn = 0
    for t, s in zip(y_true, scores):
        p = 1 if s >= threshold else 0
        if p and t:
            tp += 1
        elif p and not t:
            fp += 1
        elif t:
            fn += 1
        else:
            tn += 1
    div = lambda a, b: a / b if b else 0.0
    prec, rec, spec = div(tp, tp + fp), div(tp, tp + fn), div(tn, tn + fp)
    f1 = div(2 * prec * rec, prec + rec)
    return [prec, rec, spec, f1, (tp + tn) / len(y_true)]

