stats-logloss.solution:
import math

def log_loss(X, y, coefs):
    total = 0.0
    for row, t in zip(X, y):
        z = coefs[0] + sum(c * v for c, v in zip(coefs[1:], row))
        if z >= 0:
            p = 1 / (1 + math.exp(-z))
        else:
            ez = math.exp(z)
            p = ez / (1 + ez)
        p = min(max(p, 1e-15), 1 - 1e-15)
        total += t * math.log(p) + (1 - t) * math.log(1 - p)
    return -total / len(y)

